&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;
&lt;code&gt;^&lt;/code&gt; Spikes&lt;/td&gt;
&lt;td&gt;Deadly&lt;/td&gt;
&lt;td&gt;Deadly&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;
&lt;code&gt;o&lt;/code&gt; Sun mote&lt;/td&gt;
&lt;td&gt;Collect&lt;/td&gt;
&lt;td&gt;Collect&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;
&lt;code&gt;E&lt;/code&gt; Solstice Shrine&lt;/td&gt;
